format long

syms x
fx = exp(3*x)*sin(2*x);

a = 0;
b = 2;

% 求精确值
I_exact = int(fx, x, a, b);
I_exact = double(I_exact);
fprintf('精确值 I = %.12f\n\n', I_exact);

N = [10 20 40 80 160 320];

fprintf('   n          左点法误差         梯形法误差        抛物线法误差\n');
fprintf('------------------------------------------------------------------\n');

for k = 1:length(N)
    n = N(k);
    h = (b-a)/n;

    I_left = 0;
    I_trap = 0;
    I_simp = 0;

    % 左点法
    for i = 1:n
        xj = a + (i-1)*h;
        fxj = subs(fx, x, xj);
        I_left = I_left + fxj*h;
    end
    I_left = double(I_left);

    % 梯形法
    for i = 1:n
        xj = a + (i-1)*h;
        xi = a + i*h;
        fxj = subs(fx, x, xj);
        fxi = subs(fx, x, xi);
        I_trap = I_trap + (fxj + fxi)*h/2;
    end
    I_trap = double(I_trap);

    % Simpson法
    if mod(n,2) ~= 0
        error('Simpson法要求分段数 n 为偶数');
    end

    for i = 1:2:n
        x0 = a + (i-1)*h;
        x1 = x0 + h;
        x2 = x0 + 2*h;

        fx0 = subs(fx, x, x0);
        fx1 = subs(fx, x, x1);
        fx2 = subs(fx, x, x2);

        I_simp = I_simp + (h/3)*(fx0 + 4*fx1 + fx2);
    end
    I_simp = double(I_simp);

    % 误差
    err_left = abs((I_left - I_exact)/I_exact);
    err_trap = abs((I_trap - I_exact)/I_exact);
    err_simp = abs((I_simp - I_exact)/I_exact);

    fprintf('%5d     %16.8e   %16.8e   %16.8e\n', ...
            n, err_left, err_trap, err_simp);
end

clc; clear;

c = [6; 12];

A = [-1 -3;
      3 -1];
b = [-7; 4];

Aeq = [];
beq = [];

lb = [0; 0];
ub = [];

[x, fval] = linprog(c, A, b, Aeq, beq, lb, ub);

disp('最优解 x = ');
disp(x);
disp('最优值 fval = ');
disp(fval);

clear; clc; close all;

mu = [0 0];
Sigma = [1 1; 1 3];

[X, Y] = meshgrid(-4:0.1:4, -6:0.1:6);
xy = [X(:), Y(:)];

pdf_val = mvnpdf(xy, mu, Sigma);
PDF = reshape(pdf_val, size(X));

figure;
surf(X, Y, PDF);
shading interp;
grid on;
title('二维正态分布的联合概率密度图');
xlabel('x');
ylabel('y');
zlabel('f(x,y)');

cdf_val = mvncdf(xy, mu, Sigma);
CDF = reshape(cdf_val, size(X));

figure;
surf(X, Y, CDF);
shading interp;
grid on;
title('二维正态分布的联合分布函数图');
xlabel('x');
ylabel('y');
zlabel('F(x,y)');

clear; clc; close all;

mu = 4000;
sigma = 100;
a = 70;
b = 0.02;
c = 5;

costfun = @(T) ( a - c*(1 - normcdf(T, mu, sigma)) + ...
    b * integral(@(x) (T - x).*normpdf(x, mu, sigma), -Inf, T) ) ./ T;

[T_opt, minCost] = fminbnd(costfun, 3500, 4500);

fprintf('最佳更换周期 T = %.4f 小时\n', T_opt);
fprintf('对应的最小单位时间平均成本 = %.6f 元/小时\n', minCost);

T = 3500:1:4500;
G = arrayfun(costfun, T);

figure;
plot(T, G, 'LineWidth', 1.5);
grid on;
hold on;
plot(T_opt, minCost, 'ro', 'MarkerSize', 8, 'LineWidth', 1.5);
title('考虑回收价值时的单位时间平均成本函数');
xlabel('更换周期 T（小时）');
ylabel('单位时间平均成本');
legend('G(T)', '最优点', 'Location', 'best');
hold off;

clc; clear;

x = [0.0864 0.0744 0.0864 0.0752 0.0760 ...
     0.0954 0.0936 0.1016 0.0800 0.0880];

n = length(x);
xbar = mean(x);
s = std(x);

mu0 = 0.08;
mu1 = 0.086;

alpha_list = [0.01 0.05 0.10 0.20 0.30];
beta_list = zeros(size(alpha_list));

for k = 1:length(alpha_list)
    alpha = alpha_list(k);

    t_alpha = tinv(1-alpha, n-1);

    delta = (mu1 - mu0) / (s/sqrt(n));
    beta_list(k) = nctcdf(t_alpha, n-1, delta);
end

disp('alpha 与 beta 对照表');
disp('   alpha         beta');
disp([alpha_list(:), beta_list(:)]);

clc; clear; close all;

