load('BrainFeatures_100.mat');

X = [MeanClustering(:), GlobalEfficiency(:)];

Xz = zscore(X);

K = 3;

[idx,C] = kmeans(Xz, K, 'Replicates',10);

figure;

gscatter(Xz(:,1), Xz(:,2), idx, 'rgb', 'osd', 8);

hold on;

plot(C(:,1), C(:,2), ...
    'kx', ...
    'MarkerSize',14, ...
    'LineWidth',3);

xlabel('平均聚类系数（标准化）');
ylabel('全局效率（标准化）');

title('K-means 聚类结果（K=3)');
grid on;
